"""Bind P039 XML Page.Title independently from its outlined SWF heading."""
import argparse,pathlib,hashlib,json,xml.etree.ElementTree as E
p=argparse.ArgumentParser();p.add_argument('--source-root',type=pathlib.Path,required=True);p.add_argument('--ir',type=pathlib.Path,required=True);p.add_argument('--check',action='store_true');a=p.parse_args()
rel='G6-G8-shared/NMS002/L2/index.xml';raw=(a.source_root/rel).read_bytes();sha=hashlib.sha256(raw).hexdigest();assert len(raw)==12845 and sha=='550aee4286e8a701caf3dc58360f709a606561db8b766057ac36720833d7ff61'
xml=E.fromstring(raw);pages=list(xml.iter('Page'));assert len(pages)==64;page=pages[38];assert page.text.strip()=='IN/L2IN24.swf' and page.attrib['Title']=='Percent Practice';assert not [e for e in xml.iter('SubPageTitle')if (e.text or '').strip()==page.text.strip()]
irraw=a.ir.read_bytes();assert hashlib.sha256(irraw).hexdigest()=='afee7a2fa13b67694d609f7ed3828bebb5d7aceafe754f0c9160d39fb3aac5d7';ir=json.loads(irraw);assert ir['domains']['root']['frames'][5][0]['characterId']==108
obj={'animationId':'shared-nms002-l02-p039','sourceXml':{'path':rel,'bytes':len(raw),'sha256':sha},'globalPageOrdinal':39,'sourcePageReference':page.text.strip(),'title':page.attrib['Title'],'spanishPageTitle':None,'courseHeading':'Fractions, Decimals, and Percents Concepts:','activityHeading':'Instruction','headingSourceShape':108,'headingSource':ir['art']['108']['source'],'headingQualification':'Maintained transcription of source outlined shape108, checked against composed source image; original-runtime typography acceptance pending.'}
s='// Generated by scripts/generate-nms-l02-p039-title-v1.py. Do not edit.\nexport const P039_PAGE_TITLE='+json.dumps(obj,separators=(',',':'))+' as const;\n';target=pathlib.Path(__file__).resolve().parents[1]/'packages/demos/src/generated/nms-l02-p039-page-title-source-v1.ts'
